package org.example;

import org.example.model.Color;
import org.example.model.GameState;
import org.example.ui.BoardView;
import javafx.application.Application;
import javafx.geometry.Insets;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.layout.BorderPane;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;

import java.util.List;
import java.util.Objects;

public class ChessApp extends Application {

    private BoardView board;
    private final Label status = new Label();
    private final Button undoButton = new Button("Undo move");

    @Override
    public void start(Stage stage) {
        board = new BoardView(new GameState());
        board.setOnPositionChanged(this::updateStatus);

        Button newGameButton = new Button("New game");
        newGameButton.setOnAction(e -> board.newGame(new GameState()));

        undoButton.setOnAction(e -> board.undo());

        Button flipButton = new Button("Flip board");
        flipButton.setOnAction(e -> board.flip());

        status.getStyleClass().add("status");
        status.setWrapText(true);
        for (Button b : List.of(newGameButton, undoButton, flipButton)) {
            b.setMaxWidth(Double.MAX_VALUE);   // stretch to sidebar width
        }

        VBox sidebar = new VBox(12, status, newGameButton, undoButton, flipButton);
        sidebar.setPadding(new Insets(0, 0, 0, 20));
        sidebar.setPrefWidth(220);

        BorderPane root = new BorderPane();
        root.setCenter(board);
        root.setRight(sidebar);
        root.setPadding(new Insets(20));

        Scene scene = new Scene(root);
        scene.getStylesheets().add(Objects.requireNonNull(
                ChessApp.class.getResource("styles/chess.css"),
                "chess.css not found in src/main/resources/com/example/chess/styles/"
        ).toExternalForm());

        stage.setTitle("Chess");
        stage.setScene(scene);
        stage.setResizable(false);
        stage.show();

        updateStatus();
    }

    /** Called after every move, undo and new game. */
    private void updateStatus() {
        GameState game = board.getGame();
        Color toMove = game.getTurnToMove();
        String side  = (toMove == Color.WHITE) ? "White" : "Black";
        String other = (toMove == Color.WHITE) ? "Black" : "White";

        boolean inCheck = game.isInCheck(toMove);
        boolean noMoves = board.getLegalMoves().isEmpty();

        if (noMoves && inCheck)  status.setText("Checkmate. " + other + " wins.");
        else if (noMoves)        status.setText("Stalemate. It's a draw.");
        else if (inCheck)        status.setText(side + " to move. Check!");
        else                     status.setText(side + " to move");

        undoButton.setDisable(true);
    }

    public static void main(String[] args) {
        launch(args);
    }
}